"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["78448"],{39120(e,t,n){n.r(t),n.d(t,{metadata:()=>r,default:()=>l,frontMatter:()=>c,contentTitle:()=>d,toc:()=>h,assets:()=>p});var r=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-participant-getproductidname","title":"Get product ID and name","description":"Retrieving API described as generating the product ID and product name; declared with a bare string request body and a participant-code response.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-participant-getproductidname.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-participant-getproductidname","permalink":"/docs/pr-18/docs/nhcx/v1/api/registry/endpoints/registry-participant-getproductidname","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Get product ID and name","sidebar_label":"Get product ID and name","sidebar_class_name":"api-method api-method--post","description":"Retrieving API described as generating the product ID and product name; declared with a bare string request body and a participant-code response.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Get product owner","permalink":"/docs/pr-18/docs/nhcx/v1/api/registry/endpoints/registry-product-getowner"},"next":{"title":"Overview","permalink":"/docs/pr-18/docs/nhcx/v1/api/onboarding/"}}'),a=n(62540),i=n(43023),o=n(75064),s=JSON.parse('{"id":"registry_participant_getproductidname","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/participant/getProductIdName","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Get product ID and name","title":"Get product ID and name","description":"Retrieving API described as generating the product ID and product name; declared with a bare string request body and a participant-code response.\\n\\n### Business purpose\\n\\nThe OpenAPI document describes this endpoint with the same sentence as /product/getowner, \\"This API is to generate the product ID and product Name\\", and it belongs to the payer product lifecycle alongside /product/link, /product/delink and /product/getowner. Its documented purpose is to resolve product identity information within the participant service. The specification is thin: the request body is declared as a bare string, the response is ParticipantCreateResponse (participant_code only), and the operationId participantCreatePost is reused from the participant-creation endpoints, so treat the operationId as non-unique.\\n\\n### When to use\\n\\nUse it only where your NHCX instance documents a concrete contract for it, typically when you need product identity resolved from a string key held by the participant service. It plays no part in claim-side workflows and is not listed in either sandbox exit checklist. For resolving a product to its owning payer, /product/getowner has the clearer request schema; for discovering a member\'s products, use /participant/get/policies.\\n\\n### Preconditions\\n\\n- A valid Bearer token from the client-credentials call (POST /get/session, form-urlencoded client_ID, client_secret, grant_type=client_credentials); tokens last 1200 seconds, so refresh before expiry.\\n- HTTP headers Accept: application/json, Content-Type: application/json and bearer_auth: Bearer <token> (the participant service uses bearer_auth, not Authorisation).\\n- Base path for the participant service: https://apisbx.ABDM.gov.in/pmjay/sbxhcx/participanthcxservice (sandbox) or https://apisprod.NHA.gov.in/pmjay/hcx/participanthcxservice (production).\\n- This is a synchronous plain-JSON registry call: no JWE envelope, no x-hcx-* protocol headers and no correlation ID are involved.\\n- The request body is declared in the OpenAPI document as a bare JSON string rather than an object; the docs do not say what the string should contain.\\n- The product concerned should have been registered by its payer through /product/link.\\n\\n### Postconditions\\n\\nReturns HTTP 200 with ParticipantCreateResponse, whose only field, participant_code, is optional. No callback follows and no state change is documented. Failures return 400, 404 or 500 with the ErrorResponse envelope. Because the description promises a product ID and name while the schema returns a participant code, verify the actual body returned by your instance before depending on either interpretation.\\n\\n### Common mistakes\\n\\n- Posting a JSON object when the schema declares a bare string body, or the reverse, and getting a 400.\\n- Expecting productid and productname fields in the response; the declared response carries only participant_code.\\n- Confusing it with /product/getowner because both carry the same description.\\n- Matching on operationId participantCreatePost in generated clients, which collides with the participant-creation operations.\\n- Omitting the Accept header or the Bearer prefix on bearer_auth.\\n\\n### Best practices\\n\\n- Confirm the request and response contract against your instance\'s live OpenAPI document before integrating.\\n- Prefer /product/getowner for owner resolution and /participant/get/policies for member products; use this call only where it is specifically required.\\n- Log both the raw request string and the full response body so the actual behaviour can be reconciled with the specification.\\n- Keep the Bearer token fresh and retry once on 401.\\n\\n### Related scenario\\n\\nA TPA\'s integration team is generating a client from the participant service OpenAPI document and notices that /participant/getProductIdName shares its operationId with participant creation and its description with /product/getowner. Rather than wire it into the admission flow, they exercise it once in the sandbox with a product key, record the participant_code returned, and decide to rely on /product/getowner and /participant/get/policies for production. The member journey therefore runs link, get policies, InsurancePlan request and preauthorisation without this call.\\n\\n### Specification\\n\\nChapter [Participants and policies](/docs/nhcx/v1/registries) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"_note","type":"string","required":false,"description":"","encrypted":false},{"name":"_body","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"_note":"The OpenAPI document declares the request body as a bare JSON string; shown here as the string value that would be posted.","_body":"PRD-FLOATER-01"},"responses":[{"status":"200","description":"Returns HTTP 200 with ParticipantCreateResponse, whose only field, participant_code, is optional.","example":{"participant_code":"100234@sbx"}}],"tag":"Other operations","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/getProductIdName \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"_note\\": \\"The OpenAPI document declares the request body as a bare JSON string; shown here as the string value that would be posted.\\",\\n  \\"_body\\": \\"PRD-FLOATER-01\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/getProductIdName \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"_note\\": \\"The OpenAPI document declares the request body as a bare JSON string; shown here as the string value that would be posted.\\",\\n  \\"_body\\": \\"PRD-FLOATER-01\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/getProductIdName\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"_note\\": \\"The OpenAPI document declares the request body as a bare JSON string; shown here as the string value that would be posted.\\",\\n        \\"_body\\": \\"PRD-FLOATER-01\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/getProductIdName\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"_note\\": \\"The OpenAPI document declares the request body as a bare JSON string; shown here as the string value that would be posted.\\",\\n    \\"_body\\": \\"PRD-FLOATER-01\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"Get product ID and name",sidebar_label:"Get product ID and name",sidebar_class_name:"api-method api-method--post",description:"Retrieving API described as generating the product ID and product name; declared with a bare string request body and a participant-code response.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-registry.yaml",generated:!0},d,p={},h=[];function u(e){return(0,a.jsx)(o.A,{operation:s})}function l(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(u,{...e})}):u(e)}}}]);